// ============================================================
// SAFETY NET - Verificación de ejecución de herramientas (B&B GAS)
// ============================================================
// Se ejecuta después de "AI Agent1" (requiere returnIntermediateSteps = true).
// Si la respuesta del bot indica que se completó un paso del flujo que
// OBLIGA a ejecutar herramientas pero esas herramientas NO se ejecutaron,
// se fuerza un reintento (force_recovery) indicándole al Agente cuáles faltan.
//
// Salidas (campo `action`):
//   passthrough             -> responder tal cual
//   force_recovery          -> reintentar el Agente con `recovery_message`
//   needs_llm_verification  -> posible despedida sin cierre: la valida AI Agent2
//
// Guarda anti-loop: $runIndex es el nº de corrida de ESTE nodo dentro de la
// ejecución. Se permiten hasta 2 reintentos; luego se deja pasar la respuesta.
//
// REGLAS DE ENVÍO DE MAIL:
//  - enviarMail debe ejecutarse AL MENOS una vez por pedido/cancelación.
//  - Si enviarMail ya se ejecutó, NUNCA se reintenta nada que pueda duplicarlo.
//  - Si SetPedido/SetClientes ya se ejecutaron pero falta enviarMail, el
//    reintento pide ejecutar SOLO enviarMail (sin repetir IDPROD/SetPedido).
//  - Si no se ejecutó ninguna herramienta con efectos, el reintento es el normal.
// ============================================================
const agentOutput = $input.first().json;
const outputText = String(agentOutput.output || '');
const canRetry = $runIndex < 2;

// Herramientas ejecutadas en TODAS las corridas del Agente de esta ejecución
// (en un reintento, intermediateSteps solo trae las de la última corrida).
let steps = [];
for (let i = 0; i <= $runIndex; i++) {
  try {
    for (const it of $('AI Agent1').all(0, i)) {
      steps = steps.concat(it.json.intermediateSteps || []);
    }
  } catch (e) {
    // corrida inexistente: se ignora
  }
}
if (!steps.length) steps = agentOutput.intermediateSteps || [];

const called = (name) =>
  steps.some(s => (s.action?.tool || '').toLowerCase().startsWith(name.toLowerCase()));

// Herramientas con efectos secundarios
const SIDE_EFFECT_TOOLS = ['SetPedido', 'SetClientes', 'enviarMail'];
const sideEffectAlreadyDone = SIDE_EFFECT_TOOLS.some(t => called(t));

const triggerData = $('When chat message received').first().json;
const userMsg = String(triggerData.chatInput || '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .trim();

const passthrough = () => [{
  json: { action: 'passthrough', output: outputText, intermediateSteps: steps }
}];

// ============================================================
// CAPA 1: ¿La respuesta completa un paso que exige herramientas?
// (cada regla: marcador en la respuesta -> herramientas obligatorias)
// ============================================================
const AFFIRMATIVE = /^(si|sii+|dale|ok|okey|oka|confirmo|confirmado|confirmar|correcto|perfecto|de acuerdo|esta bien|listo|va|vale|bueno|joya|genial)\b/i;

const RULES = [
  {
    id: 'datos_cliente',
    when: /queremos confirmar que tus datos|veo que es tu primera vez|vamos a registrarte/i.test(outputText),
    tools: ['GetClientes']
  },
  {
    id: 'precio',
    when: /resumen de tu pedido|el precio de [^\n]*? es \$/i.test(outputText),
    tools: ['GetPrecios']
  },
  {
    // Solo cuando el cliente confirma el resumen (no al re-mostrar fechas ya obtenidas)
    id: 'fechas',
    when: /para qu[eé] fecha/i.test(outputText)
      && !/no es posible asignar un horario|n[uú]mero entre 1 y 5/i.test(outputText)
      && AFFIRMATIVE.test(userMsg),
    tools: ['IDPROD']
  },
  {
    id: 'localidad',
    when: /selecciona tu localidad|no contamos con cobertura|m[uú]ltiples distribuidores/i.test(outputText)
      || (/nombre completo/i.test(outputText) && /^\D*\d{4}\D*$/.test(userMsg)),
    tools: ['GetLocalidades']
  },
  {
    id: 'alta_cliente',
    when: /te registramos en el sistema/i.test(outputText),
    tools: ['IDCLIENT', 'SetClientes']
  },
  {
    // GetClientes (solo lectura) no es obligatorio acá: no justifica un reintento
    id: 'pedido_guardado',
    when: /tu pedido fue guardado con [eé]xito|n[uú]mero de pedido:/i.test(outputText),
    tools: ['SetPedido', 'HistorialPedidos', 'enviarMail']
  },
  {
    id: 'cancelacion',
    when: /solicitud de cancelaci[oó]n fue enviada/i.test(outputText),
    tools: ['enviarMail']
  }
];

const missing = [];
for (const rule of RULES) {
  if (!rule.when) continue;
  for (const tool of rule.tools) {
    if (!called(tool) && !missing.includes(tool)) missing.push(tool);
  }
}

if (missing.length && canRetry) {
  const mailMissing = missing.includes('enviarMail');

  // Caso A: ya hubo efectos (SetPedido/SetClientes) o mail, pero falta enviarMail
  // -> reintento acotado: SOLO enviarMail, sin repetir nada más.
  if (sideEffectAlreadyDone && mailMissing && !called('enviarMail')) {
    const m = outputText.match(/n[uú]mero de pedido:\s*(\d+)/i);
    const pedidoTxt = m ? ' del pedido ' + m[1] : '';
    return [{
      json: {
        action: 'force_recovery',
        reason: 'falta_enviarMail',
        recovery_message:
          '[SISTEMA - NO MOSTRAR AL USUARIO] El pedido ya fue guardado, pero NO se envió el mail de notificación' + pedidoTxt + '. Ejecutá ÚNICAMENTE la herramienta enviarMail, UNA sola vez, con los datos ya obtenidos. NO ejecutes IDPROD, SetPedido, SetClientes ni ninguna otra herramienta, y NO generes un nuevo número de pedido. Luego repetí exactamente el mismo mensaje de confirmación que ya le diste al cliente (mismo número de pedido).',
        output: outputText,
        intermediateSteps: steps
      }
    }];
  }

  // Caso B: enviarMail ya se ejecutó (o faltó otra herramienta pero ya hubo efectos):
  // no se reintenta para no duplicar pedido ni mail.
  // Caso C: no hubo ningún efecto todavía -> reintento normal.
  if (!sideEffectAlreadyDone) {
    return [{
      json: {
        action: 'force_recovery',
        reason: 'tools_faltantes: ' + missing.join(', '),
        recovery_message:
          '[SISTEMA - NO MOSTRAR AL USUARIO] En tu respuesta anterior avanzaste en el flujo pero NO ejecutaste estas herramientas obligatorias: ' +
          missing.join(', ') +
          '. Ejecutalas ahora (solo las que faltan; no repitas las ya ejecutadas, en especial enviarMail que se ejecuta UNA SOLA VEZ por evento) y luego respondé nuevamente al usuario con el mensaje correspondiente a este paso, usando únicamente los datos que devuelvan las herramientas.',
        output: outputText,
        intermediateSteps: steps
      }
    }];
  }
}

// ============================================================
// CAPA 2: Derivación (summary) o cierre (alert) ya resueltos
// ============================================================
if (/【summary:/i.test(outputText)) return passthrough();
if (/【alert:\s*"?close_conversation"?】/i.test(outputText)) return passthrough();

// ============================================================
// CAPA 3: Palabras clave de despedida SIN alert ni summary
// ============================================================
const FAREWELL_KEYWORDS = /asesor|contactar[áa]|nos comunicamos|te vamos a contactar|un representante|en breve|a la brevedad|hasta luego|hasta pronto|fue un placer|cualquier consulta|no dudes en|\bchau\b|\bbye\b|suerte/i;

if (!FAREWELL_KEYWORDS.test(outputText) || !canRetry) return passthrough();

return [{
  json: {
    action: 'needs_llm_verification',
    output: outputText,
    intermediateSteps: steps
  }
}];

